import os
import shutil
import struct
import subprocess
import tempfile
import xml.etree.ElementTree as ET
import zipfile
from pathlib import Path


ANDROID_NS = "http://schemas.android.com/apk/res/android"
NO_INDEX = 0xFFFFFFFF


def tr(key, **values):
    return notch_t(key).format(**values)


def _u16(data, offset):
    return struct.unpack_from("<H", data, offset)[0]


def _u32(data, offset):
    return struct.unpack_from("<I", data, offset)[0]


def _decode_length8(data, offset):
    first = data[offset]
    if first & 0x80:
        return ((first & 0x7F) << 8) | data[offset + 1], offset + 2
    return first, offset + 1


def _decode_length16(data, offset):
    first = _u16(data, offset)
    if first & 0x8000:
        return ((first & 0x7FFF) << 16) | _u16(data, offset + 2), offset + 4
    return first, offset + 2


def _read_string_pool(data, chunk_offset):
    header_size = _u16(data, chunk_offset + 2)
    chunk_size = _u32(data, chunk_offset + 4)
    string_count = _u32(data, chunk_offset + 8)
    flags = _u32(data, chunk_offset + 16)
    strings_start = _u32(data, chunk_offset + 20)
    offsets_start = chunk_offset + header_size
    strings_base = chunk_offset + strings_start
    chunk_end = chunk_offset + chunk_size
    is_utf8 = bool(flags & 0x100)
    strings = []

    for index in range(string_count):
        relative = _u32(data, offsets_start + index * 4)
        cursor = strings_base + relative
        if cursor >= chunk_end:
            raise ValueError(tr("manifest_string_offset_invalid"))

        if is_utf8:
            _, cursor = _decode_length8(data, cursor)
            byte_length, cursor = _decode_length8(data, cursor)
            value = data[cursor : cursor + byte_length].decode("utf-8", errors="replace")
        else:
            char_length, cursor = _decode_length16(data, cursor)
            byte_length = char_length * 2
            value = data[cursor : cursor + byte_length].decode("utf-16le", errors="replace")
        strings.append(value)

    return strings


def _typed_value(strings, raw_index, value_type, value_data):
    if raw_index != NO_INDEX and raw_index < len(strings):
        return strings[raw_index]
    if value_type == 0x03 and value_data < len(strings):
        return strings[value_data]
    if value_type == 0x12:
        return bool(value_data)
    if value_type in (0x10, 0x11):
        return value_data
    return value_data


def _binary_manifest_elements(data):
    if len(data) < 8 or _u16(data, 0) != 0x0003:
        raise ValueError(tr("manifest_binary_unrecognized"))

    root_header_size = _u16(data, 2)
    root_size = min(_u32(data, 4), len(data))
    offset = root_header_size
    strings = None
    elements = []

    while offset + 8 <= root_size:
        chunk_type = _u16(data, offset)
        header_size = _u16(data, offset + 2)
        chunk_size = _u32(data, offset + 4)
        if header_size < 8 or chunk_size < header_size or offset + chunk_size > root_size:
            raise ValueError(tr("manifest_chunk_corrupt"))

        if chunk_type == 0x0001:
            strings = _read_string_pool(data, offset)
        elif chunk_type == 0x0102:
            if strings is None or chunk_size < 36:
                raise ValueError(tr("manifest_string_pool_missing"))

            element_name_index = _u32(data, offset + 20)
            if element_name_index >= len(strings):
                raise ValueError(tr("manifest_element_index_invalid"))
            element_name = strings[element_name_index]
            attribute_start = _u16(data, offset + 24)
            attribute_size = _u16(data, offset + 26)
            attribute_count = _u16(data, offset + 28)
            if attribute_size < 20:
                raise ValueError(tr("manifest_attribute_size_invalid"))

            attributes = {}
            attributes_offset = offset + 16 + attribute_start
            for index in range(attribute_count):
                attr_offset = attributes_offset + index * attribute_size
                if attr_offset + 20 > offset + chunk_size:
                    raise ValueError(tr("manifest_attribute_out_of_bounds"))
                name_index = _u32(data, attr_offset + 4)
                raw_index = _u32(data, attr_offset + 8)
                if name_index >= len(strings):
                    continue
                value_type = data[attr_offset + 15]
                value_data = _u32(data, attr_offset + 16)
                attributes[strings[name_index]] = _typed_value(
                    strings, raw_index, value_type, value_data
                )
            elements.append((element_name, attributes))

        offset += chunk_size

    return elements


def _text_manifest_elements(data):
    root = ET.fromstring(data)
    elements = []
    for element in root.iter():
        attributes = {}
        for key, value in element.attrib.items():
            if key.startswith("{" + ANDROID_NS + "}"):
                key = key.split("}", 1)[1]
            elif ":" in key:
                key = key.rsplit(":", 1)[1]
            attributes[key] = value
        tag = element.tag.rsplit("}", 1)[-1]
        elements.append((tag, attributes))
    return elements


def _as_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value != 0
    return str(value).strip().lower() in {"1", "true", "yes"}


def inspect_apk(apk_path):
    try:
        with zipfile.ZipFile(apk_path) as archive:
            manifest = archive.read("AndroidManifest.xml")
    except (OSError, zipfile.BadZipFile, KeyError) as error:
        raise ValueError(tr("manifest_read_failed", error=error)) from error

    stripped = manifest.lstrip()
    elements = (
        _text_manifest_elements(manifest)
        if stripped.startswith(b"<")
        else _binary_manifest_elements(manifest)
    )
    relevant = [(name, attrs) for name, attrs in elements if name in {"manifest", "application"}]
    if not relevant:
        raise ValueError(tr("manifest_elements_missing"))

    flags = {"debuggable": False, "testOnly": False}
    for _, attributes in relevant:
        for key in flags:
            if key in attributes:
                flags[key] = flags[key] or _as_bool(attributes[key])
    flags["is_debug"] = flags["debuggable"] or flags["testOnly"]
    return flags


def extract_apkm(apkm_path):
    temp_root = os.environ.get("NOTCH_TEMP_DIR") or tempfile.mkdtemp(prefix="apkm-")
    dest_dir = os.path.join(temp_root, "apkm-contents")
    os.makedirs(dest_dir, exist_ok=True)
    try:
        with zipfile.ZipFile(apkm_path) as archive:
            apk_names = [
                name
                for name in archive.namelist()
                if name.lower().endswith(".apk") and not name.endswith("/")
            ]
            if not apk_names:
                raise ValueError(tr("apkm_no_apk_inside"))
            paths = []
            for name in apk_names:
                target = os.path.join(dest_dir, os.path.basename(name))
                with archive.open(name) as source, open(target, "wb") as out:
                    shutil.copyfileobj(source, out)
                paths.append(target)
    except zipfile.BadZipFile as error:
        raise ValueError(tr("apkm_extract_failed", error=error)) from error
    paths.sort(
        key=lambda path: (
            0 if os.path.basename(path) == "base.apk" else 1,
            os.path.basename(path),
        )
    )
    return paths


def find_adb():
    candidates = [shutil.which("adb")]
    for variable in ("ANDROID_SDK_ROOT", "ANDROID_HOME"):
        if os.environ.get(variable):
            candidates.append(str(Path(os.environ[variable]) / "platform-tools" / "adb"))
    candidates.extend(
        [
            str(Path.home() / "Library" / "Android" / "sdk" / "platform-tools" / "adb"),
            "/opt/homebrew/bin/adb",
            "/usr/local/bin/adb",
        ]
    )
    for candidate in candidates:
        if candidate and os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    raise RuntimeError(tr("adb_not_found"))


def list_devices(adb):
    process = subprocess.run(
        [adb, "devices", "-l"], capture_output=True, text=True, timeout=15
    )
    if process.returncode != 0:
        message = (process.stderr or process.stdout).strip()
        raise RuntimeError(tr("adb_devices_failed", message=message))

    ready = []
    unavailable = []
    for raw_line in process.stdout.splitlines()[1:]:
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        serial, state = parts[0], parts[1]
        properties = {}
        for token in parts[2:]:
            if ":" in token:
                key, value = token.split(":", 1)
                properties[key] = value
        model = properties.get("model") or properties.get("device") or properties.get("product") or tr("generic_device")
        label = f"{model.replace('_', ' ')} · {serial}"
        device = {"serial": serial, "state": state, "label": label}
        if state == "device":
            ready.append(device)
        else:
            unavailable.append(device)
    return ready, unavailable


def choose_device(devices):
    if len(devices) == 1:
        return devices[0]

    script = """
on run argv
    set dialogTitle to item 1 of argv
    set dialogPrompt to item 2 of argv
    set installLabel to item 3 of argv
    set cancelLabel to item 4 of argv
    set deviceChoices to items 5 thru -1 of argv
    set selectedDevice to choose from list deviceChoices with title dialogTitle with prompt dialogPrompt OK button name installLabel cancel button name cancelLabel without multiple selections allowed and empty selection allowed
    if selectedDevice is false then return ""
    return item 1 of selectedDevice
end run
"""
    process = subprocess.run(
        [
            "/usr/bin/osascript",
            "-e",
            script,
            "--",
            tr("install_apk_title"),
            tr("choose_device_prompt"),
            tr("install_button"),
            tr("cancel_button"),
            *[item["label"] for item in devices],
        ],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if process.returncode != 0 or not process.stdout.strip():
        return None
    selected = process.stdout.strip()
    return next((item for item in devices if item["label"] == selected), None)


def confirm_debug_install(apk_name, device_label, flags):
    reasons = []
    if flags.get("debuggable"):
        reasons.append("debuggable")
    if flags.get("testOnly"):
        reasons.append("testOnly")
    reason = "、".join(reasons) or "debug"
    message = tr("debug_confirm_message", reason=reason, apk=apk_name, device=device_label)
    script = """
on run argv
    set dialogMessage to item 1 of argv
    set dialogTitle to item 2 of argv
    set cancelLabel to item 3 of argv
    set installLabel to item 4 of argv
    display dialog dialogMessage with title dialogTitle buttons {cancelLabel, installLabel} default button installLabel cancel button cancelLabel with icon caution
    return button returned of result
end run
"""
    process = subprocess.run(
        [
            "/usr/bin/osascript",
            "-e",
            script,
            "--",
            message,
            tr("debug_install_title"),
            tr("cancel_button"),
            tr("install_button"),
        ],
        capture_output=True,
        text=True,
        timeout=120,
    )
    return process.returncode == 0 and process.stdout.strip() == tr("install_button")


def install_packages(adb, device, package_paths, allow_test):
    if len(package_paths) > 1:
        command = [adb, "-s", device["serial"], "install-multiple", "-r"]
    else:
        command = [adb, "-s", device["serial"], "install", "-r"]
    if allow_test:
        command.append("-t")
    command.extend(package_paths)
    process = subprocess.run(command, capture_output=True, text=True, timeout=240)
    output = "\n".join(
        part.strip() for part in (process.stdout, process.stderr) if part and part.strip()
    )
    if process.returncode != 0 or "Success" not in output:
        raise RuntimeError(
            tr(
                "install_failed",
                device=device["label"],
                output=output or tr("adb_no_details"),
            )
        )
    return output


def main():
    apk_path = os.environ.get("NOTCH_FILE", "").strip()
    if not apk_path:
        raise RuntimeError(tr("no_apk_received"))
    suffix = Path(apk_path).suffix.lower()
    if suffix not in {".apk", ".apkm"}:
        raise RuntimeError(tr("apk_only"))
    if not os.path.isfile(apk_path):
        raise RuntimeError(tr("apk_missing"))

    package_paths = [apk_path]
    if suffix == ".apkm":
        package_paths = extract_apkm(apk_path)

    flags = inspect_apk(package_paths[0])
    adb = find_adb()
    devices, unavailable = list_devices(adb)
    if not devices:
        details = ", ".join(f"{item['serial']} ({item['state']})" for item in unavailable)
        suffix = tr("current_devices", details=details) if details else ""
        raise RuntimeError(tr("no_ready_devices") + suffix)

    device = choose_device(devices)
    if device is None:
        notch_result(summary=tr("install_cancelled"), details=Path(apk_path).name)
        return

    use_test_flag = False
    if flags["is_debug"]:
        if not confirm_debug_install(Path(apk_path).name, device["label"], flags):
            notch_result(
                summary=tr("install_cancelled"),
                details=f"{Path(apk_path).name}\n{device['label']}",
            )
            return
        use_test_flag = True

    output = install_packages(adb, device, package_paths, use_test_flag)
    mode = tr("mode_debug") if use_test_flag else tr("mode_normal")
    notch_result(
        summary=tr("install_success"),
        details=tr(
            "success_details",
            apk=Path(apk_path).name,
            device=device["label"],
            mode=mode,
            output=output,
        ),
    )


if __name__ == "__main__":
    main()
